// Before: one cohesive Transfer method enforcing one invariant.
-class Transfer {
-  execute(from: Account, to: Account, amount: Money): void {
-    if (amount.gt(from.balance)) throw new InsufficientFunds();
-    from.balance = from.balance.minus(amount);
-    to.balance = to.balance.plus(amount);
-  }
-}

// After: "SRP applied" — four classes.
+class TransferValidator {
+  validate(from: Account, amount: Money): void {
+    if (amount.gt(from.balance)) throw new InsufficientFunds();
+  }
+}
+class BalanceDebiter  { debit(a: Account, m: Money)  { a.balance = a.balance.minus(m); } }
+class BalanceCrediter { credit(a: Account, m: Money) { a.balance = a.balance.plus(m); } }
+class TransferOrchestrator {
+  constructor(private v: TransferValidator, private d: BalanceDebiter, private c: BalanceCrediter) {}
+  execute(from: Account, to: Account, amount: Money): void {
+    this.v.validate(from, amount);
+    this.d.debit(from, amount);
+    this.c.credit(to, amount);
+  }
+}
+// AuditLogger (logs every transfer for compliance) was NOT extracted —
+// still inlined inside execute() in the production version of this file.
